          VALUES ?matchedLabel { "IP address"@en "SQL injection"@en "access control"@en "activation function"@en "artificial intelligence"@en "asymmetric encryption"@en "attention mechanism"@en "authentication"@en "authorization"@en "backpropagation"@en "batch normalization"@en "batch size"@en "certificate"@en "congestion control"@en "content security policy"@en "convolutional neural network"@en "cost function"@en "cross-entropy"@en "cross-site request forgery"@en "cross-site scripting"@en "cryptographic hash"@en "cryptography"@en "decryption"@en "deep learning"@en "digital signature"@en "domain name system"@en "dropout"@en "encryption"@en "epoch"@en "exploit"@en "feature"@en "few-shot learning"@en "firewall"@en "flow control"@en "gradient descent"@en "handshake"@en "hyperparameter"@en "hypertext transfer protocol"@en "ip address"@en "label"@en "layer normalization"@en "learning rate"@en "long short-term memory"@en "loss function"@en "machine learning"@en "malware"@en "mean squared error"@en "neural network"@en "online learning"@en "overfitting"@en "phishing"@en "port"@en "private key"@en "public key"@en "rectified linear unit"@en "recurrent neural network"@en "regularization"@en "reinforcement learning"@en "retransmission"@en "router"@en "same-origin policy"@en "sandbox"@en "self-attention"@en "self-supervised learning"@en "sliding window"@en "socket"@en "softmax"@en "sql injection"@en "stochastic gradient descent"@en "subnet"@en "supervised learning"@en "switch"@en "symmetric encryption"@en "test set"@en "training set"@en "transfer learning"@en "transport layer security"@en "underfitting"@en "unsupervised learning"@en "validation set"@en "vulnerability"@en "zero-shot learning"@en }
